{
  "schemaVersion": 1,
  "date": "2026-10-25",
  "interview": [
    {
      "id": "gateway-failover",
      "articleIds": [
        "2026-10-25-top-1"
      ],
      "question": "生成AIの応答先を自動で切り替える場合、どこまで継続できるかをどう考えますか。",
      "answer": "障害の種類と切り替えられる時点を分けます。AgentCore Gatewayでは503や応答待ちで別モデルへ送れます。ただし、ストリーミング開始後の中断は引き継げません。サーキットブレーカーの結果も20回の試験なので、追加費用と途中で切れた画面の扱いを確認します。"
    },
    {
      "id": "japanese-token-cost",
      "articleIds": [
        "2026-10-25-top-2"
      ],
      "question": "日本語を扱うAIサービスの費用を、どう見積もりますか。",
      "answer": "文字数と料金を分け、実際の入力使用量に単価を掛けます。今回、Qwen3.8-Flashは165トークンでしたが、243トークンの別モデルの方が安い結果でした。ただし段落は一つです。自社文書でもテンプレート分を分け、推論を含む出力使用量と回答品質を別々に確認します。"
    },
    {
      "id": "multitab-progress",
      "articleIds": [
        "2026-10-25-top-3"
      ],
      "question": "複数のタブで学習記録を編集するとき、古いデータの上書きをどう防ぎますか。",
      "answer": "版番号を増やすだけでは防げません。Web Locksの同じ排他ロックの中で保存値を読み直し、読み込んだ時のJSONと違えば止めます。storageイベントは通知用です。非対応ブラウザには原子的な保証がないため、記録の退避と最新状態の再読込を用意します。"
    },
    {
      "id": "outbox-delivery",
      "articleIds": [
        "2026-10-25-top-4"
      ],
      "question": "DB更新後の通知を失わないために、どのような設計を選びますか。",
      "answer": "業務データと未送信イベントを同じトランザクションで残し、別のリレーが送ります。ただしOutboxでも、送信後の完了記録に失敗すると重複します。受信側はイベントIDで二重処理を防ぎます。原文はSQLiteと模擬キューの実験なので、実環境の永続性や並列実行は別に確かめます。"
    },
    {
      "id": "tts-quality-review",
      "articleIds": [
        "2026-10-25-top-5"
      ],
      "question": "日本語の合成音声で、読み間違いをどう確認して修正しますか。",
      "answer": "台本の読みと、kana-whisperが音声から認識した読みを比べ、人が聴いて判断します。台本を認識へ渡さないのは、期待した答えに引っ張られないためです。ただし一致しても正読の証明にはなりません。文ごとに版を残し、修正した一文だけを再点検してから採用します。"
    }
  ],
  "review": [
    {
      "id": "review-failure-boundary",
      "articleIds": [
        "2026-10-25-top-1"
      ],
      "question": "フォールバックが成功しても、何を別に確認する必要がありますか。",
      "points": {
        "zh": "核对实际响应目标、尝试次数和费用；流式开始后的中断不会自动续接，网关限流与授权拒绝也不属于可绕开的错误。20次熔断比较仅是特定环境的结果。",
        "ja": "実際に応答したターゲットと試行数・費用をログで確認する。ストリーミング開始後の中断、Gatewayの制限、認可拒否は別の境界。20回の比較を一般的な保証にしない。"
      }
    },
    {
      "id": "review-storage-vs-outbox",
      "articleIds": [
        "2026-10-25-top-3",
        "2026-10-25-top-4"
      ],
      "question": "ブラウザの排他ロックとOutboxは、それぞれ何を守りますか。",
      "points": {
        "zh": "Web Locks让合作标签页在读取、比较、写入期间互斥，冲突后停止旧页保存。Outbox在一个DB事务中留下业务行和待发事件，但外部投递仍可重复，需要消费端去重。二者都不能把各自边界之外的操作自动变成原子事务。",
        "ja": "Web Locksは協調するタブの再読込・比較・保存を直列化し、古い保存を止める。Outboxは業務行と送るべき事実を同じDBへ確定するが、外部への再送は重複し得る。どちらも保護範囲の外まで原子的にするものではない。"
      }
    },
    {
      "id": "review-proxy-vs-quality",
      "articleIds": [
        "2026-10-25-top-2",
        "2026-10-25-top-5"
      ],
      "question": "少ないトークン数や音声認識の一致だけで、品質を判断できますか。",
      "points": {
        "zh": "Token数量需结合单价、输出计费和内容正确性；单段翻译不能给所有日文模型排名。音频识别与台本一致也可能漏错，机器差异、人的听取和采用版本必须分别记录。",
        "ja": "トークン数は単価や出力使用量、回答の正しさと分けて見る。一段落で日本語全体を順位付けしない。音声の認識一致も正読保証ではなく、機械点検、人の聴取、採用版を別々に記録する。"
      }
    }
  ]
}
